$ErrorActionPreference='Stop'
function ReadFunctions([string]$file) {
 $result=[System.Collections.Generic.List[object]]::new()
 $current=$null
 foreach($line in Get-Content -LiteralPath $file) {
  if($line -match '^([0-9a-f]{16}) <(.+)>:$') {
   $current=[pscustomobject]@{Start=[Convert]::ToInt64($Matches[1],16);Name=$Matches[2];Code=[System.Collections.Generic.List[object]]::new()}
   $result.Add($current)
  } elseif($null -ne $current -and $line -match '^\s+([0-9a-f]{1,8}):\s+(\S.*)$') {
   $current.Code.Add([pscustomobject]@{Address=[Convert]::ToInt64($Matches[1],16);Text=$Matches[2]})
  }
 }
 foreach($function in $result) {
  while($function.Code.Count -gt 0 -and $function.Code[$function.Code.Count-1].Text -match '^nop') {$function.Code.RemoveAt($function.Code.Count-1)}
 }
 return $result
}
$r30=@(ReadFunctions 'artifacts/benchmark-queue/6ae23a991ef945e896bc1214fee5759d/stdout.log')
$r31=@(ReadFunctions 'artifacts/benchmark-queue/d8880c685740475381cc661a037c912c/stdout.log')
foreach($entry in @([pscustomobject]@{Version='r30';Functions=$r30},[pscustomobject]@{Version='r31';Functions=$r31})) {
 foreach($f in $entry.Functions) {
  $role=if($f.Name -match 'HandwrittenDefaultPairs') {'Hand'} else {'Relation'}
  $prefixes=@($f.Code | Where-Object {$_.Text -eq 'lock'})
  $calls=@($f.Code | Where-Object {$_.Text -match '^callq'})
  $end=$f.Code[$f.Code.Count-1].Address+1
  [pscustomobject]@{Version=$entry.Version;Role=$role;Start=('0x{0:x}' -f $f.Start);EndExclusive=('0x{0:x}' -f $end);Bytes=$end-$f.Start;Rows=$f.Code.Count;LockPrefixes=$prefixes.Count;Instructions=$f.Code.Count-$prefixes.Count;CallSites=$calls.Count} | ConvertTo-Json -Compress
  foreach($call in $calls) {
   $target=$call.Text -replace '<.*>','<symbol>'
   'CALL '+$entry.Version+' '+$role+' '+('0x{0:x}' -f $call.Address)+' '+$target
  }
 }
}
